INSERT INTO public.community_activities ("id", "teacher_id", "title", "template_type", "content_json", "upvotes", "created_at", "teacher_name")
VALUES
  ('18101821-cafe-4000-8000-000000000001', 'c00a0eeb-9c0b-4ef8-bb6d-6bb9bd380a55', 'La Gesta Heroica de la Independencia de México (1810 - 1821)', 'custom_builder', '{"title":"La Gesta Heroica de la Independencia de México (1810 - 1821)","blocks":[{"id":"node-indep-1","data":{"style":"dialogue","content":"¡Hijos míos! Doña Josefa Ortiz de Domínguez nos ha enviado aviso urgente desde Querétaro: ¡nuestra conspiración ha sido delatada! No queda un minuto por perder. He mandado repicar la campana de nuestra parroquia para convocar al pueblo. Tomemos el estandarte y marchemos juntos por la libertad, la justicia y la abolición de los tributos injustos. ¿Están listos para transformar el destino de México?","speakerName":"Don Miguel Hidalgo y Costilla","speakerAvatar":"🔔"},"type":"text_narrative","title":"1. Madrugada de Dolores: El Llamado a la Libertad","position":{"x":60,"y":150},"isCollapsed":false,"isStartNode":true},{"id":"node-indep-2","data":{"instructions":"Ordena cronológicamente los 4 periodos fundamentales de la gesta heroica (1810 a 1821):","randomizeStart":true,"stepsInCorrectOrder":["1810 - 1811: Etapa de Inicio (Grito de Dolores, toma de la Alhóndiga y primeras batallas con Miguel Hidalgo e Ignacio Allende).","1811 - 1815: Etapa de Organización (Campañas militares de José María Morelos, Congreso de Chilpancingo y Sentimientos de la Nación).","1815 - 1820: Etapa de Resistencia (Guerra de guerrillas en las serranías del sur con Vicente Guerrero y Francisco Xavier Mina).","1821: Etapa de Consumación (El Abrazo de Acatempan, proclamación del Plan de Iguala y entrada triunfal del Ejército Trigarante)."]},"type":"ordering_sequence","title":"2. Las 4 Grandes Etapas de la Independencia","position":{"x":380,"y":150},"isCollapsed":false},{"id":"node-indep-3","data":{"pairs":[{"left":"Miguel Hidalgo y Costilla","right":"Padre de la Patria y Decreto de Abolición de la Esclavitud"},{"left":"Josefa Ortiz de Domínguez","right":"Heroína de Querétaro que alertó a los insurgentes"},{"left":"José María Morelos y Pavón","right":"Siervo de la Nación y autor de los Sentimientos de la Nación"},{"left":"Vicente Guerrero","right":"\"La patria es primero\" y consumador con el Ejército Trigarante"}],"instructions":"Empareja a cada protagonista histórico con su contribución trascendental a la patria:","timeLimitSeconds":60},"type":"drag_drop_match","title":"3. Héroes y Heroínas de la Patria","position":{"x":700,"y":150},"isCollapsed":false},{"id":"node-indep-4","data":{"clueText":"En las tertulias secretas de Querétaro, los conjurados protegían sus mensajes con un lema supremo de 9 letras que sintetiza el derecho inalienable de todos los seres humanos a no ser sometidos ni esclavizados:","hintText":"Palabra de 9 letras. Comienza con \"LIBER...\" y termina con D. Es el ideal sagrado de 1810.","secretAnswer":"LIBERTAD"},"type":"secret_code_puzzle","title":"4. El Santo y Seña de la Conspiración Secreta","position":{"x":1020,"y":150},"isCollapsed":false},{"id":"node-indep-5","data":{"maxHp":150,"bossName":"Comandante Realista Torcuato Trujillo ⚔️","spriteKey":"shadow_golem","attackPower":20,"backgroundScene":"temple","victoryCondition":"defeat_boss"},"type":"boss_enemy","title":"5. Batalla del Monte de las Cruces","position":{"x":1340,"y":150},"isCollapsed":false},{"id":"node-indep-6","data":{"xpAmount":350,"badgeIcon":"Award","badgeName":"Libertador de la Patria 🔔🇲🇽","chestRarity":"legendary","coinsAmount":60,"badgeUnlockId":"badge-indep-master-2026"},"type":"reward_chest","title":"6. Cofre de la Gloria: ¡Consumación de la Independencia!","position":{"x":1660,"y":150},"isCollapsed":false}],"pdaNem":"Fase 5 - Ética, Naturaleza y Sociedades: Analiza las causas y las cuatro etapas del movimiento de Independencia de la Nueva España, valorando el ideario de los Sentimientos de la Nación y los derechos de soberanía e igualdad.","faseNem":"Fase 5","subject":"Historia y Formación Cívica","metadata":{"pdas":["Fase 5 - Ética, Naturaleza y Sociedades: Analiza las causas y las cuatro etapas del movimiento de Independencia de la Nueva España, valorando el ideario de los Sentimientos de la Nación y los derechos de soberanía e igualdad.","Fase 5 - Lenguajes: Produce e interpreta narraciones orales, biografías ilustradas y debates sobre los héroes y heroínas de la Independencia nacional."],"title":"La Gesta Heroica de la Independencia de México (1810 - 1821)","pdaNem":"Fase 5 - Ética, Naturaleza y Sociedades: Analiza las causas y las cuatro etapas del movimiento de Independencia de la Nueva España, valorando el ideario de los Sentimientos de la Nación y los derechos de soberanía e igualdad.","faseNem":"Fase 5","subject":"Historia y Formación Cívica","taskType":"activity_flow","xpReward":350,"subjectId":"sub-hist","targetAge":"Primaria Alta y Secundaria (10 - 15 años)","livesCount":3,"coinsReward":60,"description":"Clase magistral interactiva y gamificada. Recorre las 4 etapas de la lucha armada mediante diálogo inmersivo con Miguel Hidalgo, reto cronológico de etapas, emparejamiento táctico de próceres, acertijo de escape room de la conspiración, combate épico en Monte de las Cruces y el Cofre Legendario de la Patria.","campoFormativo":"Ética, Naturaleza y Sociedades","totalTimeLimit":0,"camposFormativos":["Ética, Naturaleza y Sociedades","Lenguajes"],"streakMultiplier":true,"ejesArticuladores":["Pensamiento Crítico","Apropiación de las Culturas a través de la Lectura y la Escritura","Interculturalidad Crítica"]},"targetAge":"Primaria Alta y Secundaria (10 - 15 años)","connections":[{"id":"conn-indep-1-2","label":"next","sourceNodeId":"node-indep-1","targetNodeId":"node-indep-2"},{"id":"conn-indep-2-3","label":"next","sourceNodeId":"node-indep-2","targetNodeId":"node-indep-3"},{"id":"conn-indep-3-4","label":"next","sourceNodeId":"node-indep-3","targetNodeId":"node-indep-4"},{"id":"conn-indep-4-5","label":"next","sourceNodeId":"node-indep-4","targetNodeId":"node-indep-5"},{"id":"conn-indep-5-6","label":"success","sourceNodeId":"node-indep-5","targetNodeId":"node-indep-6"}],"description":"Clase magistral interactiva y gamificada. Recorre las 4 etapas de la lucha armada mediante diálogo inmersivo con Miguel Hidalgo, reto cronológico de etapas, emparejamiento táctico de próceres, acertijo de escape room de la conspiración, combate épico en Monte de las Cruces y el Cofre Legendario de la Patria.","campoFormativo":"Ética, Naturaleza y Sociedades"}'::jsonb, 980, '2026-09-03T14:57:51.184+00:00', 'Prof. Israel López Ángeles'),
  ('18101821-cafe-4000-8000-000000000002', 'c00a0eeb-9c0b-4ef8-bb6d-6bb9bd380a55', 'Gimnasio Cerebral: Héroes y Heroínas de la Independencia', 'custom_builder', '{"title":"Gimnasio Cerebral: Héroes y Heroínas de la Independencia","blocks":[{"id":"node-prog-1","data":{"targetWpm":175,"wordCount":198,"readingText":"En los albores de la lucha por la Independencia, una joven criolla de gran cultura e inteligencia revolucionó la insurgencia desde las sombras de la Ciudad de México: Leona Vicario.\n\nPerteneciente a una familia acaudalada, Leona decidió poner toda su fortuna, joyas e ingenio al servicio de la patria. Formó parte de la red clandestina conocida como \"Los Guadalupes\", una organización secreta de abogados, médicos y damas que operaba en la capital novohispana vigilando los movimientos de los ejércitos virreinales.\n\nDisfrazando correos entre canastas de víveres y carretas de leña, Leona enviaba a los campamentos insurgentes medicinas, ropa, pólvora y, sobre todo, tipos tipográficos metálicos para que Andrés Quintana Roo pudiera imprimir \"El Ilustrador Americano\", el primer periódico rebelde que difundía el pensamiento libertario.\n\nEn marzo de 1813, uno de sus mensajeros fue interceptado. Alertada del peligro, intentó huir pero fue capturada y encerrada en el Convento de Belén de las Mochas. A pesar de los duros interrogatorios de las autoridades virreinales, jamás delató a ninguno de sus compañeros. Meses después, tres insurgentes disfrazados de soldados realistas la rescataron en una audaz fuga a caballo, llevándola hasta los campamentos de José María Morelos en Oaxaca. Por su valentía moral y estratégica, fue declarada \"Benemérita y Dulcísima Madre de la Patria\".","timeLimitSeconds":65,"comprehensionQuestions":[{"id":"q-prog-1","options":["Financiar la imprenta secreta y enviar tipos tipográficos para el periódico rebelde","Dirigir los ejércitos armados en la batalla del Monte de las Cruces","Redactar el Acta de Independencia en el Palacio Virreinal","Comandar una flota de barcos en el puerto de Veracruz"],"question":"¿Cuál fue la aportación crucial de Leona Vicario para la difusión de los ideales insurgentes?","explanation":"Leona Vicario financió la compra de caracteres de imprenta para publicar \"El Ilustrador Americano\", el periódico que transmitía los ideales libertarios.","correctIndex":0},{"id":"q-prog-2","options":["Porque operaban dentro de la Ciudad de México espiando al gobierno virreinal","Porque no creían en la Independencia y apoyaban al Virrey","Porque sólo se reunían para festividades religiosas","Porque pretendían huir al extranjero con el tesoro real"],"question":"¿Por qué la red secreta de \"Los Guadalupes\" requería máxima discreción en la capital?","explanation":"Los Guadalupes eran espías y simpatizantes que informaban a los insurgentes sobre tropas realistas desde el corazón del poder novohispano.","correctIndex":0},{"id":"q-prog-3","options":["Su inquebrantable lealtad al negarse a delatar a la red de conspiradores","Aceptar un soborno del Virrey para obtener su libertad inmediata","Renunciar por escrito a sus ideas libertarias para conservar sus bienes","Escapar en la primera noche fingiendo ser una guardia"],"question":"¿Qué rasgo ético fundamental distinguió a Leona Vicario durante su encierro en el convento?","explanation":"Pese a la amenaza de perder sus bienes y su vida, Leona jamás reveló nombres ni rutas secretas de la insurgencia.","correctIndex":0}]},"type":"timed_reading_block","title":"1. Barrido Visual & Lectura Veloz: El Enigma de Leona Vicario","position":{"x":60,"y":150},"isCollapsed":false,"isStartNode":true},{"id":"node-prog-2","data":{"pairs":[{"left":"Don Miguel Hidalgo y Costilla","right":"Decretó la abolición de la esclavitud en Guadalajara en 1810"},{"left":"Doña Josefa Ortiz de Domínguez","right":"Alertó a Ignacio Allende en San Miguel mediante taconazos en el suelo"},{"left":"Don José María Morelos y Pavón","right":"Proclamó los Sentimientos de la Nación y creó los tres poderes de gobierno"},{"left":"Don Vicente Guerrero","right":"Mantuvo la guerra de resistencia con el lema sagrado \"La patria es primero\""}],"instructions":"Deduce y empareja a cada prócer histórico con la decisión crucial que transformó la lucha emancipadora:","timeLimitSeconds":60},"type":"drag_drop_match","title":"2. Matriz de Próceres: Conexiones Tácticas y Pensamiento Estratégico","position":{"x":380,"y":150},"isCollapsed":false},{"id":"node-prog-3","data":{"clueText":"En el Congreso de Chilpancingo de 1813, Morelos plasmó el principio supremo por el cual el poder emana directamente del pueblo y sólo en él reside el derecho a elegir su forma de gobierno sin sumisión a monarquías extranjeras:","hintText":"Palabra de 9 letras. Comienza con \"SOBER...\" y concluye en \"A\". Es el concepto cumbre del artículo 5° de los Sentimientos de la Nación.","secretAnswer":"SOBERANIA"},"type":"secret_code_puzzle","title":"3. Deducción Criptográfica: El Manifiesto de Chilpancingo","position":{"x":700,"y":150},"isCollapsed":false},{"id":"node-prog-4","data":{"instructions":"Ordena con rapidez mental los 4 acontecimientos determinantes según su secuencia cronológica exacta:","randomizeStart":true,"stepsInCorrectOrder":["1. Septiembre 1810: Miguel Hidalgo e Ignacio Allende inician la lucha en Dolores y abolen la esclavitud.","2. Septiembre 1813: José María Morelos instala el Congreso de Chilpancingo y proclama los Sentimientos de la Nación.","3. Febrero 1821: Vicente Guerrero y Agustín de Iturbide sellan la alianza en Acatempan mediante el Plan de Iguala.","4. Septiembre 1821: El Ejército Trigarante entra a la Ciudad de México y se consuma la Independencia."]},"type":"ordering_sequence","title":"4. Jerarquización Cronológica: Las Huellas de los Próceres","position":{"x":1020,"y":150},"isCollapsed":false},{"id":"node-prog-5","data":{"maxHp":160,"bossName":"Centinela del Olvido Historiográfico ⚔️","spriteKey":"shadow_golem","attackPower":20,"backgroundScene":"temple","victoryCondition":"defeat_boss"},"type":"boss_enemy","title":"5. Duelo Cognitivo: El Guardián del Olvido Histórico","position":{"x":1340,"y":150},"isCollapsed":false},{"id":"node-prog-6","data":{"xpAmount":420,"badgeIcon":"Award","badgeName":"Estratega del Pensamiento Crítico 🧠🇲🇽","chestRarity":"legendary","coinsAmount":80,"badgeUnlockId":"badge-heroes-cognitive-2026"},"type":"reward_chest","title":"6. Cofre del Pensamiento Crítico: Medalla Siervo de la Nación","position":{"x":1660,"y":150},"isCollapsed":false}],"pdaNem":"Fase 5 - Ética, Naturaleza y Sociedades: Analiza críticamente los proyectos de nación e ideales de los héroes y heroínas de la Independencia, valorando el papel histórico de las mujeres insurgentes y la defensa de la justicia social.","faseNem":"Fase 5","subject":"Historia, Formación Cívica y Lenguajes","metadata":{"pdas":["Fase 5 - Ética, Naturaleza y Sociedades: Analiza críticamente las causas y los ideales de los próceres de la Independencia de México, valorando el papel de las mujeres insurgentes y el ideario de los Sentimientos de la Nación.","Fase 5 - Lenguajes: Aplica destrezas de lectura veloz, localización de pistas textuales e interpretación crítica en textos biográficos e históricos."],"title":"Gimnasio Cerebral: Héroes y Heroínas de la Independencia","pdaNem":"Fase 5 - Ética, Naturaleza y Sociedades: Analiza críticamente los proyectos de nación e ideales de los héroes y heroínas de la Independencia, valorando el papel histórico de las mujeres insurgentes y la defensa de la justicia social.","faseNem":"Fase 5","subject":"Historia, Formación Cívica y Lenguajes","taskType":"activity_flow","xpReward":420,"subjectId":"sub-hist-lang","targetAge":"Primaria Alta (10 - 12 años • 5° y 6° Grado)","livesCount":3,"coinsReward":80,"description":"Entrenamiento cognitivo de alto rendimiento: comprensión lectora rápida (PPM), inferencia textual, discriminación de información y lógica histórica. Descubre las decisiones estratégicas de Leona Vicario, Miguel Hidalgo, José María Morelos y Vicente Guerrero.","campoFormativo":"Ética, Naturaleza y Sociedades","totalTimeLimit":0,"camposFormativos":["Ética, Naturaleza y Sociedades","Lenguajes"],"streakMultiplier":true,"ejesArticuladores":["Pensamiento Crítico","Apropiación de las Culturas a través de la Lectura y la Escritura","Igualdad de Género"]},"targetAge":"Primaria Alta (10 - 12 años • 5° y 6° Grado)","connections":[{"id":"conn-prog-1-2","label":"next","sourceNodeId":"node-prog-1","targetNodeId":"node-prog-2"},{"id":"conn-prog-2-3","label":"next","sourceNodeId":"node-prog-2","targetNodeId":"node-prog-3"},{"id":"conn-prog-3-4","label":"next","sourceNodeId":"node-prog-3","targetNodeId":"node-prog-4"},{"id":"conn-prog-4-5","label":"next","sourceNodeId":"node-prog-4","targetNodeId":"node-prog-5"},{"id":"conn-prog-5-6","label":"success","sourceNodeId":"node-prog-5","targetNodeId":"node-prog-6"}],"description":"Entrenamiento cognitivo de alto rendimiento: comprensión lectora rápida (PPM), inferencia textual, discriminación de información y lógica histórica. Descubre las decisiones estratégicas de Leona Vicario, Miguel Hidalgo, José María Morelos y Vicente Guerrero.","campoFormativo":"Ética, Naturaleza y Sociedades"}'::jsonb, 920, '2026-09-03T15:57:51.186+00:00', 'Prof. Israel López Ángeles')
